reference_solution:
def count_at_least(scores, threshold):
    count = 0
    for score in scores:
        if score >= threshold:
            count = count + 1
    return count


n = int(input())
threshold = int(input())
scores = []
for i in range(n):
    scores.append(int(input()))

print(count_at_least(scores, threshold))
